function interact(){if(mode==='ambush'){ambushInteract();return;}if(mode==='skirmish')return;const p=intel.clone().add(new THREE.Vector3(2,0,0));if(stage===0&&player.distanceTo(p)<5){if(mode==='coop'&&peer.role==='guest'&&peer.connected)peer.send({type:'interact'});else advanceStory();}}
