function shoot(){if(state!=='playing'||hostPaused||healing>0)return;if(weapon.ammo===0&&weapon.reloadRemaining===0){reload();return;}if(!weapon.fire())return;lastShot={pos:player.clone(),t:elapsed};const config=gunConfig();recoil=Math.min(recoil+.027,.12);pitch=Math.min(pitch+(aim?config.recoil*.55:config.recoil),1.35);yaw+=(rand()-.5)*config.recoil*.45;muzzle.intensity=4;flash.visible=true;sound('shot');camera.updateMatrixWorld();const dir=new THREE.Vector3(0,0,-1).applyQuaternion(camera.quaternion);let spread=config.spread*(aim?1:5)*(crouch?.65:1)*(keys.has('KeyW')||keys.has('KeyA')||keys.has('KeyD')?2:1);dir.x+=(rand()-.5)*spread;dir.y+=(rand()-.5)*spread;dir.normalize();if(mode==='coop'&&peer.role==='guest'){peer.send({type:'shot',dir:dir.toArray()});tracer(camera.position.clone(),camera.position.clone().addScaledVector(dir,150),0xffd79b);}else hitScan(camera.position.clone(),dir,config);}
