function humanEyes(){const out=[player.clone().setY(player.y+stanceHeight)];if(mode==='coop'&&peer.connected&&remote.g.visible&&remote.hp>0)out.push(remote.g.position.clone().setY(remote.g.position.y+(remote.crouch?.95:1.7)));return out;}
